const cfg=$('Config').first().json;
const staticData=$getWorkflowStaticData('global');
staticData.seen=staticData.seen||{};
const mail=items[0].json;
const subject=String(mail.subject||'');
const body=String(mail.textHtml||mail.html||mail.textPlain||mail.text||'');
const blob=`${subject}\n${body}`;
if(!/roscrea/i.test(blob)) return [];
const urls=[...blob.matchAll(/https?:\/\/(?:www\.)?daft\.ie\/[^\s"'<>]+/gi)].map(m=>m[0].replace(/[),.;]+$/,''));
const uniq=[...new Set(urls)].filter(u=>/for-rent|sharing|property-for-rent/i.test(u));
const out=[];
for (const url of uniq){const idMatch=url.match(/(\d{6,})/);const id=`daft-mail-${idMatch?idMatch[1]:url}`; if(staticData.seen[id]) continue; out.push({json:{...cfg,id,source:'daft-email',title:subject||'Daft alert',price:'',beds:'',propertyType:'',seller:'',url}});} return out;

const staticData = $getWorkflowStaticData('global');
staticData.seen = staticData.seen || {};
const cfg = $('Config').first().json;
const candidate = $('Parse Daft Emails').item.json;
const htmlRaw = items[0].json;
const html = typeof htmlRaw === 'string' ? htmlRaw : (htmlRaw.data || htmlRaw.body || htmlRaw.html || '');
const t = String(html || '');
if (!t || /no longer available|this ad has been removed|ad has expired/i.test(t)) {
  staticData.seen[candidate.id] = Date.now();
  return [];
}
let title = candidate.title;
let price = candidate.price;
let seller = '';
let beds = '';
let propertyType = '';
let url = candidate.url;
const m = t.match(/<script[^>]*id="__NEXT_DATA__"[^>]*>(.*?)<\/script>/);
if (m) {
  try {
    const data = JSON.parse(m[1]);
    const listing = (((data || {}).props || {}).pageProps || {}).listing;
    if (listing) {
      if (listing.state && String(listing.state).toUpperCase() !== 'PUBLISHED') {
        staticData.seen[candidate.id] = Date.now();
        return [];
      }
      title = listing.title || title;
      price = listing.price || price;
      seller = (listing.seller && listing.seller.name) || '';
      beds = listing.numBedrooms || '';
      propertyType = listing.propertyType || '';
      if (listing.seoFriendlyPath) url = `https://www.daft.ie${listing.seoFriendlyPath}`;
    }
  } catch(e) {}
}
if (!/roscrea/i.test(`${title} ${url} ${t.slice(0,2000)}`)) {
  return [];
}
staticData.seen[candidate.id] = Date.now();
const text = [
  `🚨 ROSCREA LIVE RENTAL`,
  ``,
  `📍 ${title}`,
  `💶 ${price || 'See ad'} · ${beds || '?'} · ${propertyType || ''}`.trim(),
  `👤 ${seller || 'Contact on ad'}`,
  `🟢 Status: AVAILABLE NOW`,
  `📡 Source: daft-email`,
  ``,
  `🔗 ${url}`,
  ``,
  `ACTION NOW:`,
  `1) Open link`,
  `2) Call if phone visible`,
  `3) Else Enquire immediately`
].join('\n');
return [{json:{id:candidate.id,title,price,beds,propertyType,seller,url,source:'daft-email',telegramChatId:cfg.telegramChatId,text,status:'available',foundAt:new Date().toISOString()}}];
